function smart_sort_array($set, $order) {
    // Define the comparison function
    $compare_function = function ($a, $b) use ($order) {
        if ($a['age'] == $b['age']) return 0; // If ages are equal, keep the original order

        switch ($order) {
            case 'asc':
                return $a['age'] < $b['age'] ? -1 : 1;
            case 'desc':
                return $a['age'] > $b['age'] ? -1 : 1;
            default:
                throw new InvalidArgumentException('Invalid sort order: ' . $order);
        }
    };

    usort($set, $compare_function);

    return $set;
}

// Example usage
$example_set = [
    ['name' => 'Alice', 'address' => '', 'age' => 30],
    ['name' => 'Bob', 'address' => '', 'age' => 25],
    ['name' => 'Charlie', 'address' => '', 'age' => 40]
];

// Sort by age in ascending order
$result_asc = smart_sort_array($example_set, 'asc');
print_r($result_asc);

// Sort by age in descending order
$result_desc = smart_sort_array($example_set, 'desc');
print_r($result_desc);
```

